import assert from 'node:assert/strict';
import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { once } from 'node:events';
import { runInNewContext } from 'node:vm';
import { test } from 'node:test';
import { parse } from 'yaml';
import { loadPricing, lifetimePrice } from '../assets/js/pro-pricing.js';

const pricing = parse(await readFile(new URL('../_data/pricing.yml', import.meta.url), 'utf8'));
const config = parse(await readFile(new URL('../_config.yml', import.meta.url), 'utf8'));

test('pricing follows the count boundary and rejects unavailable or invalid counts', async t => {
  const legacyPricing = { ...pricing, checkout_provider: 'revenuecat' };
  // Contract-faithful fake of the external count API, using real HTTP requests.
  const server = createServer((req, res) => {
    res.setHeader('Content-Type', 'application/json');
    if (req.url === '/unavailable') { res.writeHead(502); res.end('{"error":"upstream_unavailable"}'); return; }
    res.end(JSON.stringify({ count: req.url === '/invalid' ? -1 : Number(req.url.slice(1)), updated: new Date().toISOString() }));
  });
  server.listen(0, '127.0.0.1');
  await once(server, 'listening');
  t.after(() => new Promise(resolve => server.close(resolve)));
  const endpoint = `http://127.0.0.1:${server.address().port}`;
  for (const [count, lifetime, monthly, tier] of [[1499, 69, 4.99, 0], [1500, 119, 7.99, 1], [6500, 119, 7.99, 1]]) {
    const result = await loadPricing({ ...legacyPricing, lifetime_offer: { ...pricing.lifetime_offer, enabled: false }, count_endpoint: `${endpoint}/${count}` });
    assert.equal(result.count, count);
    assert.equal(result.pricing.lifetime, lifetime);
    assert.equal(result.pricing.monthly, monthly);
    assert.equal(result.tier, tier);
    const offerResult = await loadPricing({ ...legacyPricing, count_endpoint: `${endpoint}/${count}` });
    assert.equal(offerResult.pricing.lifetime, 49.99);
    assert.equal(offerResult.pricing.monthly, monthly);
    assert.equal(offerResult.tier, tier);
  }
  await assert.rejects(loadPricing({ ...legacyPricing, count_endpoint: `${endpoint}/invalid` }));
  await assert.rejects(loadPricing({ ...legacyPricing, count_endpoint: `${endpoint}/unavailable` }));
});

test('the lifetime offer is available before the count loads and can be disabled', () => {
  assert.equal(lifetimePrice({ ...pricing, lifetime: '...' }), 49.99);
  assert.equal(lifetimePrice({ lifetime: 119 }), 119);
  assert.equal(lifetimePrice({ ...pricing, lifetime: 119, lifetime_offer: { ...pricing.lifetime_offer, enabled: false } }), 119);
});

test('old and new purchase links retain the encoded email user ID', async () => {
  const context = { module: { exports: {} } };
  runInNewContext(await readFile(new URL('../assets/js/revenuecat-link.js', import.meta.url), 'utf8'), context);
  const email = 'buyer+pro@example.com';
  for (const [key, token] of [
    ['revenuecat_link_lifetime', 'avvnmcnfsgbmjaee'],
    ['revenuecat_link_monthly', 'dqcncujvkiumpwhk'],
    ['revenuecat_link_lifetime_119', 'qojryhrzrjfaihnq'],
    ['revenuecat_link_monthly_799', 'ttzwavolonbvapek'],
  ]) {
    assert.equal(context.module.exports.buildPurchaseUrl(config[key], email),
      `https://pay.rev.cat/${token}/buyer%2Bpro%40example.com?email=buyer%2Bpro%40example.com`);
  }
});

test('Stripe pricing works without a RevenueCat count and fails closed', async t => {
  const server = createServer((req, res) => {
    res.setHeader('Content-Type', 'application/json');
    if (req.url !== '/stripe/pricing') { res.writeHead(503); res.end('{}'); return; }
    res.end(JSON.stringify({ lifetime: 49.99, monthly: 7.99, lifetime_offer: { enabled: true, original_price: 119, amount_off: 69.01 } }));
  });
  server.listen(0, '127.0.0.1');
  await once(server, 'listening');
  t.after(() => new Promise(resolve => server.close(resolve)));
  const endpoint = `http://127.0.0.1:${server.address().port}`;
  const result = await loadPricing({ ...pricing, checkout_provider: 'stripe', stripe_endpoint: `${endpoint}/stripe`, count_endpoint: `${endpoint}/unavailable` });
  assert.equal(result.pricing.lifetime, 49.99);
  assert.equal(result.pricing.monthly, 7.99);
  assert.equal(result.count, null);
  await assert.rejects(loadPricing({ ...pricing, checkout_provider: 'stripe', stripe_endpoint: `${endpoint}/unavailable` }));
});

// Generated by tools/gen-features.mjs. Edit preview-ui/pages/_features.mjs instead.
import React from 'react';
import FeaturePage from './_feature.jsx';
export default function Page({ data }) { return <FeaturePage slug="models" data={data} />; }

import { useEffect, useState } from 'react';
import { loadPricing, lifetimePrice } from '../assets/js/pro-pricing.js';

// React adapter for the same helper used by the Liquid layouts.
export function usePricing(initialPricing) {
  const [result, setResult] = useState(null);
  const [failed, setFailed] = useState(false);
  useEffect(() => {
    let active = true;
    loadPricing(initialPricing)
      .then(value => { if (active) setResult(value); })
      .catch(() => { if (active) setFailed(true); });
    return () => { active = false; };
  }, [initialPricing]);
  return {
    pricing: result?.pricing ?? { ...initialPricing, lifetime: lifetimePrice({ ...initialPricing, lifetime: '...' }), monthly: '...' },
    count: result?.count ?? null,
    tier: result?.tier ?? null,
    failed,
    ready: result !== null,
  };
}

// One count request per page, using the existing count worker and pricing data.
// The final ladder tier has no purchase links yet; checkout has two cohorts.
const counts = new Map();

export function lifetimePrice(pricing) {
  const offer = pricing.lifetime_offer;
  return offer?.enabled
    ? Math.round((offer.original_price - offer.amount_off) * 100) / 100
    : pricing.lifetime;
}

export function loadPricing(pricing) {
  if (pricing.checkout_provider === 'stripe') {
    return fetch(`${pricing.stripe_endpoint}/pricing`, { signal: AbortSignal.timeout(8000) })
      .then(response => response.ok ? response.json() : Promise.reject(new Error('Pricing unavailable')))
      .then(current => {
        if (!Number.isFinite(current.lifetime) || !Number.isFinite(current.monthly) || current.lifetime <= 0 || current.monthly <= 0) throw new Error('Invalid pricing');
        return { count: null, tier: null, pricing: { ...pricing, ...current } };
      });
  }
  const endpoint = pricing.count_endpoint;
  if (!endpoint) return Promise.reject(new Error('Customer count endpoint missing'));
  if (!counts.has(endpoint)) {
    counts.set(endpoint, new Promise((resolve, reject) => {
      const controller = typeof AbortController === 'function' ? new AbortController() : null;
      const timeout = setTimeout(() => {
        if (controller) controller.abort();
        reject(new Error('Customer count request timed out'));
      }, 8000);
      fetch(endpoint, controller ? { signal: controller.signal } : undefined)
        .then(r => r.ok ? r.json() : Promise.reject(new Error('Customer count unavailable')))
        .then(d => {
          if (!Number.isInteger(d.count) || d.count < 0) throw new Error('Invalid customer count');
          resolve(d.count);
        })
        .catch(reject)
        .then(() => clearTimeout(timeout));
    }));
  }
  return counts.get(endpoint).then(count => {
    const tier = count >= pricing.tiers[0].until ? 1 : 0;
    return {
      count,
      tier,
      pricing: { ...pricing, lifetime: lifetimePrice({ ...pricing, lifetime: pricing.tiers[tier].lifetime }), monthly: pricing.tiers[tier].monthly },
    };
  });
}

const assert = require('node:assert/strict');
const fs = require('node:fs');
const vm = require('node:vm');

class Element {
  constructor(dataset = {}) {
    this.dataset = dataset;
    this.handlers = {};
    this.value = '';
    this.hidden = false;
    this.classList = { toggle() {} };
  }
  addEventListener(name, callback) { (this.handlers[name] ||= []).push(callback); }
  fire(name, event = {}) { (this.handlers[name] || []).forEach(callback => callback(event)); }
  setAttribute() {}
  focus() {}
  getBoundingClientRect() { return { top: 0 }; }
}

function fixture(sdk = 'normal', pageSize = '8') {
  const ids = {};
  for (const name of ['search', 'platform', 'sort', 'clear', 'more', 'empty', 'result-title', 'result-count', 'results']) {
    ids['article-' + name] = new Element();
  }
  ids['article-sort'].value = 'newest';
  const topics = ['', 'Guides', 'Articles'].map(topic => new Element({ topic }));
  const panel = new Element();
  const items = ['Guides', 'Articles'].map((topic, i) => {
    const item = new Element({ topic, platform: 'Android', date: '2026-09-30', keywords: 'Sync' });
    item.href = '/articles/result-' + i + '/?private=value';
    item.querySelector = selector => ({ textContent: selector === '.guide-card-title' ? 'Android sync' : 'Learn about sync' });
    item.closest = () => item;
    return item;
  });
  const results = ids['article-results'];
  results.appendChild = item => { items.splice(items.indexOf(item), 1); items.push(item); };
  results.querySelectorAll = () => items;
  results.contains = item => items.includes(item);
  const hub = new Element(pageSize ? { pageSize } : {});
  hub.querySelector = () => panel;
  hub.querySelectorAll = selector => selector === '.article-topic' ? topics : items;
  const impression = new Element({ analyticsView: 'design_partner_offer_viewed', analyticsPlacement: 'home_card' });
  const events = [];
  const handlers = {};
  let observerCallback;
  const timers = new Map();
  let timerId = 0;
  const window = {
    location: { pathname: pageSize ? '/' : '/articles/', href: 'https://getoffgridai.co/' },
    matchMedia: () => ({ matches: true }),
    addEventListener: (name, callback) => { handlers[name] = callback; },
    setTimeout: callback => { timers.set(++timerId, callback); return timerId; },
    clearTimeout: id => timers.delete(id)
  };
  if (sdk !== 'missing') window.posthog = {
    capture(name, properties) {
      if (sdk === 'throwing') throw new Error('blocked');
      events.push({ name, properties });
    }
  };
  const document = {
    querySelector: () => hub,
    querySelectorAll: () => [impression],
    getElementById: id => ids[id],
    addEventListener: (name, callback) => { handlers['document-' + name] = callback; }
  };
  const context = vm.createContext({ window, document, URL, IntersectionObserver: class {
    constructor(callback) { observerCallback = callback; }
    observe() {}
    unobserve() {}
  } });
  for (const file of ['site-analytics.js', 'article-hub.js']) {
    vm.runInContext(fs.readFileSync('assets/js/' + file, 'utf8'), context);
  }
  return {
    window, ids, topics, items, panel, events, handlers,
    type(value) { ids['article-search'].value = value; ids['article-search'].fire('input'); },
    tick() { const callbacks = [...timers.values()]; timers.clear(); callbacks.forEach(callback => callback()); },
    view() { observerCallback([{ target: impression, isIntersecting: true, intersectionRatio: 0.5 }]); }
  };
}

for (const pageSize of ['8', '']) {
  const f = fixture('normal', pageSize);
  assert.equal(f.events.length, 0, 'rendering alone must not send interaction events');
  f.type('android'); f.type('android sync'); f.tick();
  assert.equal(f.events.length, 1, 'typing is debounced');
  assert.equal(f.events[0].name, 'resource_search_used');
  assert.equal(f.events[0].properties.result_count, 2);
  assert.equal(f.events[0].properties.placement, pageSize ? 'home_resources' : 'articles');
  assert.equal(f.panel.hidden, true);
  f.ids['article-search'].fire('change'); f.ids['article-search'].fire('blur');
  assert.equal(f.events.length, 1, 'change and blur must not duplicate search');
  f.type(''); f.tick();
  assert.equal(f.events.at(-1).name, 'resource_search_cleared');
  assert.equal(f.panel.hidden, false);
  f.topics[1].fire('click');
  assert.equal(f.events.at(-1).properties.topic, 'Guides');
  assert.equal(f.events.at(-1).properties.result_count, 1);
  f.ids['article-platform'].value = 'Android';
  f.ids['article-platform'].fire('input'); f.ids['article-platform'].fire('change');
  assert.equal(f.events.filter(e => e.name === 'resource_device_selected').length, 1);
  f.ids['article-sort'].value = 'title'; f.ids['article-sort'].fire('change');
  assert.equal(f.events.at(-1).name, 'resource_sort_changed');
  f.ids['article-results'].fire('click', { target: f.items.find(item => !item.hidden) });
  assert.equal(f.events.at(-1).properties.position, 1);
  assert.match(f.events.at(-1).properties.destination, /^\/articles\/result-\d\/$/);
  f.ids['article-more'].fire('click');
  assert.equal(f.events.at(-1).name, 'resource_more_clicked');
  f.type('a-private-search-that-does-not-match'); f.tick();
  assert.equal(f.events.at(-1).properties.result_count, 0);
  assert.equal(f.ids['article-empty'].hidden, false);
  f.ids['article-clear'].fire('click');
  assert.equal(f.events.at(-1).name, 'resource_filters_cleared');
  assert.equal(f.ids['article-search'].value, '');
  f.view(); f.view();
  assert.equal(f.events.filter(e => e.name === 'design_partner_offer_viewed').length, 1);
  for (const name of ['design_partner_offer_clicked', 'design_partner_email_clicked']) {
    f.handlers['document-click']({ target: { closest: () => ({ dataset: { analyticsEvent: name, analyticsPlacement: 'test' } }) } });
    assert.equal(f.events.at(-1).name, name);
  }
  const payloads = JSON.stringify(f.events);
  assert.ok(!payloads.includes('android sync'));
  assert.ok(!payloads.includes('a-private-search'));
  assert.ok(!payloads.includes('private=value'));
}

for (const sdk of ['missing', 'throwing']) {
  const f = fixture(sdk);
  f.type('android'); f.tick(); f.topics[1].fire('click'); f.view();
  f.ids['article-results'].fire('click', { target: f.items.find(item => !item.hidden) });
  assert.equal(f.ids['article-empty'].hidden, true, 'tracking failure must not break results');
}
console.log('Analytics event, privacy, deduplication, and failure checks passed');

const assert = require('node:assert/strict');
const fs = require('node:fs');
const vm = require('node:vm');

const script = fs.readFileSync('assets/js/beta-download.js', 'utf8');
const fallback = 'https://github.com/off-grid-ai/OGAD/releases/download/v0.0.55-beta.112/pinned';

function link(format) {
  return {
    href: fallback,
    getAttribute(name) { return name === 'data-beta-download' ? format : null; }
  };
}

async function check(fetchResult) {
  const links = [link('AppImage'), link('deb'), link('dmg'), link('exe')];
  vm.runInNewContext(script, {
    document: { querySelectorAll() { return links; } },
    fetch() { return Promise.resolve(fetchResult); },
    Date
  });
  await new Promise(resolve => setImmediate(resolve));
  return links;
}

const release = (tag, date, assets) => ({
  tag_name: tag,
  published_at: date,
  prerelease: true,
  draft: false,
  assets: assets.map(name => ({
    name,
    state: 'uploaded',
    browser_download_url: `https://github.com/off-grid-ai/OGAD/releases/download/${tag}/${name}`
  }))
});

(async () => {
  const releases = [
    release('v0.0.54-beta.109', '2026-09-29T14:04:50Z', [
      'off-grid-ai-0.0.54-beta.109.AppImage',
      'off-grid-ai_0.0.54-beta.109_amd64.deb'
    ]),
    release('v0.0.54-beta.110', '2026-09-29T19:30:07Z', [
      'off-grid-ai-0.0.54-beta.110.AppImage',
      'off-grid-ai_0.0.54-beta.110_amd64.deb',
      'OffGrid-0.0.54-beta.110.dmg',
      'OffGrid-0.0.54-beta.110.dmg.blockmap',
      'off-grid-ai-0.0.54-beta.110-setup.exe'
    ]),
    { ...release('v0.0.54', '2026-09-29T21:02:00Z', ['off-grid-ai-0.0.54.AppImage']), prerelease: false }
  ];
  const found = await check({ ok: true, json: () => Promise.resolve(releases) });
  assert.match(found[0].href, /v0\.0\.54-beta\.110\/.*\.AppImage$/);
  assert.match(found[1].href, /v0\.0\.54-beta\.110\/.*_amd64\.deb$/);
  assert.match(found[2].href, /v0\.0\.54-beta\.110\/OffGrid-0\.0\.54-beta\.110\.dmg$/);
  assert.match(found[3].href, /v0\.0\.54-beta\.110\/.*-setup\.exe$/);

  const unavailable = await check({ ok: false });
  assert.equal(unavailable[0].href, fallback);
  assert.equal(unavailable[1].href, fallback);
  assert.equal(unavailable[2].href, fallback);
  assert.equal(unavailable[3].href, fallback);
  console.log('Beta download link assertions passed');
})().catch(error => {
  console.error(error);
  process.exitCode = 1;
});
